\u043d\u0456\u0449\u043e \u043c\u0430\u0432\u043a\u0430___\u0437\u043c\u0456\u043d\u0438\u0442\u0438_\u0435\u043b\u0435\u043c\u0435\u043d\u0442(\u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_827, \u0443\u043d\u0456\u043a___37___\u043c\u0430\u0432\u043a\u0430___\u0417\u043d\u0430\u0447\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_828, \u0443\u043d\u0456\u043a___37___\u043c\u0430\u0432\u043a\u0430___\u0417\u043d\u0430\u0447\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_829, \u0443\u043d\u0456\u043a___37___\u043c\u0430\u0432\u043a\u0430___\u0417\u043d\u0430\u0447\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_830, \u0443\u043d\u0456\u043a___15___\u043c\u0430\u0432\u043a\u0430___\u041c\u0456\u0441\u0446\u0435\u0437\u043d\u0430\u0445\u043e\u0434\u0436\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_831);
\u043d\u0456\u0449\u043e \u043c\u0430\u0432\u043a\u0430___\u043f\u0440\u0435\u0434\u043c\u0435\u0442_\u0434\u0430\u043d\u0438\u0445_\u0437\u043c\u0456\u043d\u0438\u0442\u0438_\u0435\u043b\u0435\u043c\u0435\u043d\u0442(\u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_859, \u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_860, \u0443\u043d\u0456\u043a___37___\u043c\u0430\u0432\u043a\u0430___\u0417\u043d\u0430\u0447\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_861, \u0443\u043d\u0456\u043a___37___\u043c\u0430\u0432\u043a\u0430___\u0417\u043d\u0430\u0447\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_862, \u0443\u043d\u0456\u043a___15___\u043c\u0430\u0432\u043a\u0430___\u041c\u0456\u0441\u0446\u0435\u0437\u043d\u0430\u0445\u043e\u0434\u0436\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_863);
\u043d\u0456\u0449\u043e \u043c\u0430\u0432\u043a\u0430___\u043f\u0440\u0435\u0434\u043c\u0435\u0442_\u0441\u043b\u043e\u0432\u043d\u0438\u043a\u0430_\u0437\u043c\u0456\u043d\u0438\u0442\u0438_\u0435\u043b\u0435\u043c\u0435\u043d\u0442(\u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_873, \u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_874, \u0443\u043d\u0456\u043a___37___\u043c\u0430\u0432\u043a\u0430___\u0417\u043d\u0430\u0447\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_875, \u0443\u043d\u0456\u043a___37___\u043c\u0430\u0432\u043a\u0430___\u0417\u043d\u0430\u0447\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_876, \u0443\u043d\u0456\u043a___15___\u043c\u0430\u0432\u043a\u0430___\u041c\u0456\u0441\u0446\u0435\u0437\u043d\u0430\u0445\u043e\u0434\u0436\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_877);
\u043d\u0456\u0449\u043e \u043c\u0430\u0432\u043a\u0430___\u043f\u0440\u0435\u0434\u043c\u0435\u0442_\u0441\u043f\u0438\u0441\u043a\u0443_\u0437\u043c\u0456\u043d\u0438\u0442\u0438_\u0435\u043b\u0435\u043c\u0435\u043d\u0442(\u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_887, \u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_888, \u0443\u043d\u0456\u043a___37___\u043c\u0430\u0432\u043a\u0430___\u0417\u043d\u0430\u0447\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_889, \u0443\u043d\u0456\u043a___37___\u043c\u0430\u0432\u043a\u0430___\u0417\u043d\u0430\u0447\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_890, \u0443\u043d\u0456\u043a___15___\u043c\u0430\u0432\u043a\u0430___\u041c\u0456\u0441\u0446\u0435\u0437\u043d\u0430\u0445\u043e\u0434\u0436\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_891);
\u0430\u0434\u0440\u0435\u0441\u0430 \u043c\u0430\u0432\u043a\u0430___\u043f\u043e\u043a\u043b\u0430\u0441\u0442\u0438_\u0441\u043f\u0440\u043e\u0431\u0443(\u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_906, \u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_907, \u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_908, \u043f32 \u043d\u0430\u0437\u0432\u0430_909);
\u0430\u0434\u0440\u0435\u0441\u0430 \u043c\u0430\u0432\u043a\u0430___\u0441\u0442\u0432\u043e\u0440\u0438\u0442\u0438_\u043c\u043e\u0434\u0443\u043b\u044c(\u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_915, \u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_916);
\u0430\u0434\u0440\u0435\u0441\u0430 \u043c\u0430\u0432\u043a\u0430___\u0441\u0442\u0432\u043e\u0440\u0438\u0442\u0438_\u043e\u0437\u043d\u0430\u043a\u0443(\u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_920, \u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_921, \u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_922, \u0443\u043d\u0456\u043a___37___\u043c\u0430\u0432\u043a\u0430___\u0417\u043d\u0430\u0447\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_923);
\u0430\u0434\u0440\u0435\u0441\u0430 \u043c\u0430\u0432\u043a\u0430___\u0441\u0442\u0432\u043e\u0440\u0438\u0442\u0438_\u043f\u043e\u043c\u0438\u043b\u043a\u0443(\u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_929, \u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_930);
\u0430\u0434\u0440\u0435\u0441\u0430 \u043c\u0430\u0432\u043a\u0430___\u0441\u0442\u0432\u043e\u0440\u0438\u0442\u0438_\u0441\u043b\u043e\u0432\u043d\u0438\u043a(\u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_934);
\u043d\u0456\u0449\u043e \u043c\u0430\u0432\u043a\u0430___\u0432\u0438\u0432\u0435\u0441\u0442\u0438_\u0437\u043d\u0430\u0447\u0435\u043d\u043d\u044f(\u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_937, \u0443\u043d\u0456\u043a___37___\u043c\u0430\u0432\u043a\u0430___\u0417\u043d\u0430\u0447\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_938, \u043f32 \u043d\u0430\u0437\u0432\u0430_939, \u043f32 \u043d\u0430\u0437\u0432\u0430_940);
\u0443\u043d\u0456\u043a___37___\u043c\u0430\u0432\u043a\u0430___\u0417\u043d\u0430\u0447\u0435\u043d\u043d\u044f \u043c\u0430\u0432\u043a\u0430___\u043e\u0442\u0440\u0438\u043c\u0430\u0442\u0438_\u0435\u043b\u0435\u043c\u0435\u043d\u0442(\u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_946, \u0443\u043d\u0456\u043a___37___\u043c\u0430\u0432\u043a\u0430___\u0417\u043d\u0430\u0447\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_947, \u0443\u043d\u0456\u043a___37___\u043c\u0430\u0432\u043a\u0430___\u0417\u043d\u0430\u0447\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_948, \u0443\u043d\u0456\u043a___15___\u043c\u0430\u0432\u043a\u0430___\u041c\u0456\u0441\u0446\u0435\u0437\u043d\u0430\u0445\u043e\u0434\u0436\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_949);
\u0443\u043d\u0456\u043a___37___\u043c\u0430\u0432\u043a\u0430___\u0417\u043d\u0430\u0447\u0435\u043d\u043d\u044f \u043c\u0430\u0432\u043a\u0430___\u043f\u0440\u0435\u0434\u043c\u0435\u0442_\u0434\u0430\u043d\u0438\u0445_\u043e\u0442\u0440\u0438\u043c\u0430\u0442\u0438_\u0435\u043b\u0435\u043c\u0435\u043d\u0442(\u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_963, \u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_964, \u0443\u043d\u0456\u043a___37___\u043c\u0430\u0432\u043a\u0430___\u0417\u043d\u0430\u0447\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_965, \u0443\u043d\u0456\u043a___15___\u043c\u0430\u0432\u043a\u0430___\u041c\u0456\u0441\u0446\u0435\u0437\u043d\u0430\u0445\u043e\u0434\u0436\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_966);
\u0443\u043d\u0456\u043a___37___\u043c\u0430\u0432\u043a\u0430___\u0417\u043d\u0430\u0447\u0435\u043d\u043d\u044f \u043c\u0430\u0432\u043a\u0430___\u043f\u0440\u0435\u0434\u043c\u0435\u0442_\u043f\u043e\u0441\u043b\u0456\u0434\u043e\u0432\u043d\u043e\u0441\u0442\u0456_\u043e\u0442\u0440\u0438\u043c\u0430\u0442\u0438_\u0435\u043b\u0435\u043c\u0435\u043d\u0442(\u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_975, \u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_976, \u0443\u043d\u0456\u043a___37___\u043c\u0430\u0432\u043a\u0430___\u0417\u043d\u0430\u0447\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_977, \u0443\u043d\u0456\u043a___15___\u043c\u0430\u0432\u043a\u0430___\u041c\u0456\u0441\u0446\u0435\u0437\u043d\u0430\u0445\u043e\u0434\u0436\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_978);
\u0443\u043d\u0456\u043a___37___\u043c\u0430\u0432\u043a\u0430___\u0417\u043d\u0430\u0447\u0435\u043d\u043d\u044f \u043c\u0430\u0432\u043a\u0430___\u043f\u0440\u0435\u0434\u043c\u0435\u0442_\u0441\u043b\u043e\u0432\u043d\u0438\u043a\u0430_\u043e\u0442\u0440\u0438\u043c\u0430\u0442\u0438_\u0435\u043b\u0435\u043c\u0435\u043d\u0442(\u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_986, \u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_987, \u0443\u043d\u0456\u043a___37___\u043c\u0430\u0432\u043a\u0430___\u0417\u043d\u0430\u0447\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_988, \u0443\u043d\u0456\u043a___15___\u043c\u0430\u0432\u043a\u0430___\u041c\u0456\u0441\u0446\u0435\u0437\u043d\u0430\u0445\u043e\u0434\u0436\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_989);
\u0443\u043d\u0456\u043a___37___\u043c\u0430\u0432\u043a\u0430___\u0417\u043d\u0430\u0447\u0435\u043d\u043d\u044f \u043c\u0430\u0432\u043a\u0430___\u043f\u0440\u0435\u0434\u043c\u0435\u0442_\u0441\u043f\u0438\u0441\u043a\u0443_\u043e\u0442\u0440\u0438\u043c\u0430\u0442\u0438_\u0435\u043b\u0435\u043c\u0435\u043d\u0442(\u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_997, \u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_998, \u0443\u043d\u0456\u043a___37___\u043c\u0430\u0432\u043a\u0430___\u0417\u043d\u0430\u0447\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_999, \u0443\u043d\u0456\u043a___15___\u043c\u0430\u0432\u043a\u0430___\u041c\u0456\u0441\u0446\u0435\u0437\u043d\u0430\u0445\u043e\u0434\u0436\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_1000);
\u0443\u043d\u0456\u043a___37___\u043c\u0430\u0432\u043a\u0430___\u0417\u043d\u0430\u0447\u0435\u043d\u043d\u044f \u043c\u0430\u0432\u043a\u0430___\u043f\u0440\u0435\u0434\u043c\u0435\u0442_\u0442\u0435\u043a\u0441\u0442\u0443_\u043e\u0442\u0440\u0438\u043c\u0430\u0442\u0438_\u0435\u043b\u0435\u043c\u0435\u043d\u0442(\u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_1008, \u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_1009, \u0443\u043d\u0456\u043a___37___\u043c\u0430\u0432\u043a\u0430___\u0417\u043d\u0430\u0447\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_1010, \u0443\u043d\u0456\u043a___15___\u043c\u0430\u0432\u043a\u0430___\u041c\u0456\u0441\u0446\u0435\u0437\u043d\u0430\u0445\u043e\u0434\u0436\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_1011);
\u0443\u043d\u0456\u043a___37___\u043c\u0430\u0432\u043a\u0430___\u0417\u043d\u0430\u0447\u0435\u043d\u043d\u044f \u043c\u0430\u0432\u043a\u0430___\u043e\u0442\u0440\u0438\u043c\u0430\u0442\u0438_\u043f\u0435\u0440\u0435\u0431\u0456\u0440(\u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_1027, \u0443\u043d\u0456\u043a___37___\u043c\u0430\u0432\u043a\u0430___\u0417\u043d\u0430\u0447\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_1028, \u0443\u043d\u0456\u043a___15___\u043c\u0430\u0432\u043a\u0430___\u041c\u0456\u0441\u0446\u0435\u0437\u043d\u0430\u0445\u043e\u0434\u0436\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_1029);
\u0430\u0434\u0440\u0435\u0441\u0430 \u043c\u0430\u0432\u043a\u0430___\u0441\u0442\u0432\u043e\u0440\u0438\u0442\u0438_\u043f\u0435\u0440\u0435\u0431\u0456\u0440_\u0434\u0430\u043d\u0438\u0445(\u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_1044, \u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_1045);
